23: /* Tab5 display / framebuffer glue (PinePhone-style up_fbinitialize split).
24:  *
25:  * Sequence (ESP-IDF DPI panel + selected ST712x controller):
26:  *   1. Allocate RGB565 FB (PSRAM)
27:  *   2. Host already registered by bringup
28:  *   3. configure_dpi -> panel DCS -> bind FB -> video_start -> display_on
29:  *   4. Backlight on
30:  *   5. Optional All-Pixels-On bring-up flash
31:  */
32: 
33: /****************************************************************************
34:  * Included Files
35:  ****************************************************************************/
36: 
37: #include <nuttx/config.h>
38: 
39: #include <errno.h>
40: #include <debug.h>
41: #include <string.h>
42: #include <syslog.h>
43: 
44: #include <nuttx/arch.h>
45: #include <nuttx/compiler.h>
46: #include <nuttx/kmalloc.h>
47: #include <nuttx/video/fb.h>
48: #include <nuttx/video/mipi_display.h>
49: #include <nuttx/video/mipi_dsi.h>
50: 
51: #include <arch/board/board.h>
52: 
53: #include "espressif/esp_mipi_dsi.h"
54: 
55: #include "esp32p4-tab5.h"
56: 
57: #ifdef CONFIG_ESP32P4_TAB5_LCD_ST7123
58: #  include "esp32p4_lcd_st7123.h"
59: #  define tab5_panel_initialize tab5_st7123_initialize
60: #else
61: #  include "esp32p4_lcd_st7121.h"
62: #  define tab5_panel_initialize tab5_st7121_initialize
63: #endif
64: 
65: /****************************************************************************
66:  * Pre-processor Definitions
67:  ****************************************************************************/
68: 
69: #define TAB5_FB_BPP        16
70: #define TAB5_FB_WIDTH      TAB5_MIPI_DSI_H_RES
71: #define TAB5_FB_HEIGHT     TAB5_MIPI_DSI_V_RES
72: #define TAB5_FB_STRIDE     (TAB5_FB_WIDTH * (TAB5_FB_BPP / 8))
73: #define TAB5_FB_SIZE       (TAB5_FB_STRIDE * TAB5_FB_HEIGHT)
74: 
75: #define TAB5_FB_TEST_COLOR  0xf800
76: 
77: #define TAB5_DCS_ALL_PIXELS_ON   0x23
78: #define TAB5_DCS_ALL_PIXELS_OFF  0x22
79: #define TAB5_APO_TEST_MS         1000
80: 
81: /****************************************************************************
82:  * Private Function Prototypes
83:  ****************************************************************************/
84: 
85: static int tab5_getvideoinfo(FAR struct fb_vtable_s *vtable,
86:                              FAR struct fb_videoinfo_s *vinfo);
87: static int tab5_getplaneinfo(FAR struct fb_vtable_s *vtable, int planeno,
88:                              FAR struct fb_planeinfo_s *pinfo);
89: #ifdef CONFIG_FB_UPDATE
90: static int tab5_updatearea(FAR struct fb_vtable_s *vtable,
91:                            FAR const struct fb_area_s *area);
92: #endif
93: 
94: /****************************************************************************
95:  * Private Data
96:  ****************************************************************************/
97: 
98: static struct fb_vtable_s g_tab5_vtable =
99: {
100:   .getvideoinfo = tab5_getvideoinfo,
101:   .getplaneinfo = tab5_getplaneinfo,
102: #ifdef CONFIG_FB_UPDATE
103:   .updatearea   = tab5_updatearea,
104: #endif
105: };
106: 
107: static struct fb_videoinfo_s g_tab5_video =
108: {
109:   .fmt     = FB_FMT_RGB16_565,
110:   .xres    = TAB5_FB_WIDTH,
111:   .yres    = TAB5_FB_HEIGHT,
112:   .nplanes = 1,
113: };
114: 
115: static struct fb_planeinfo_s g_tab5_plane =
116: {
117:   .fbmem   = NULL,
118:   .fblen   = TAB5_FB_SIZE,
119:   .stride  = TAB5_FB_STRIDE,
120:   .display = 0,
121:   .bpp     = TAB5_FB_BPP,
122:   .xres_virtual = TAB5_FB_WIDTH,
123:   .yres_virtual = TAB5_FB_HEIGHT,
124:   .xoffset = 0,
125:   .yoffset = 0,
126: };
127: 
128: static FAR uint16_t *g_tab5_fb;
129: static bool g_tab5_fb_ready;
130: 
131: /****************************************************************************
132:  * Private Functions
133:  ****************************************************************************/
134: 
135: /****************************************************************************
136:  * Name: tab5_getvideoinfo
137:  *
138:  * Description:
139:  *   Return the video information.
140:  *
141:  * Input Parameters:
142:  *   vtable - The vtable.
143:  *   vinfo - The video information.
144:  *
145:  * Returned Value:
146:  *   Zero on success.
147:  *
148:  ****************************************************************************/
149: 
150: static int tab5_getvideoinfo(FAR struct fb_vtable_s *vtable,
151:                              FAR struct fb_videoinfo_s *vinfo)
152: {
153:   DEBUGASSERT(vtable != NULL && vtable == &g_tab5_vtable && vinfo != NULL);
154:   memcpy(vinfo, &g_tab5_video, sizeof(*vinfo));
155:   return OK;
156: }
157: 
158: /****************************************************************************
159:  * Name: tab5_getplaneinfo
160:  *
161:  * Description:
162:  *   Return the plane information.
163:  *
164:  * Input Parameters:
165:  *   vtable - The vtable.
166:  *   planeno - The plane number.
167:  *   pinfo - The plane information.
168:  *
169:  * Returned Value:
170:  *   Zero on success, -EINVAL if the plane number is invalid.
171:  *
172:  ****************************************************************************/
173: 
174: static int tab5_getplaneinfo(FAR struct fb_vtable_s *vtable, int planeno,
175:                              FAR struct fb_planeinfo_s *pinfo)
176: {
177:   DEBUGASSERT(vtable != NULL && vtable == &g_tab5_vtable && pinfo != NULL);
178: 
179:   if (planeno != 0 || g_tab5_plane.fbmem == NULL)
180:     {
181:       return -EINVAL;
182:     }
183: 
184:   memcpy(pinfo, &g_tab5_plane, sizeof(*pinfo));
185:   return OK;
186: }
187: 
188: #ifdef CONFIG_FB_UPDATE
189: /****************************************************************************
190:  * Name: tab5_updatearea
191:  *
192:  * Description:
193:  *   Update a region of the framebuffer.
194:  *
195:  * Input Parameters:
196:  *   vtable - The vtable.
197:  *   area - The area to update.
198:  *
199:  * Returned Value:
200:  *   Zero on success, -EAGAIN if the framebuffer is not ready,
201:  *   -EINVAL if the area is out of bounds.
202:  ****************************************************************************/
203: 
204: static int tab5_updatearea(FAR struct fb_vtable_s *vtable,
205:                            FAR const struct fb_area_s *area)
206: {
207:   size_t offset;
208:   size_t len;
209: 
210:   DEBUGASSERT(vtable != NULL && vtable == &g_tab5_vtable);
211: 
212:   if (g_tab5_fb == NULL)
213:     {
214:       return -EAGAIN;
215:     }
216: 
217:   if (area == NULL)
218:     {
219:       return esp_mipi_dsi_flush_framebuffer(g_tab5_fb, TAB5_FB_SIZE);
220:     }
221: 
222:   if (area->y >= TAB5_FB_HEIGHT || area->x >= TAB5_FB_WIDTH)
223:     {
224:       return OK;
225:     }
226: 
227:   offset = (size_t)area->y * TAB5_FB_STRIDE +
228:            (size_t)area->x * (TAB5_FB_BPP / 8);
229:   len = (size_t)area->h * TAB5_FB_STRIDE;
230:   if (offset + len > TAB5_FB_SIZE)
231:     {
232:       len = TAB5_FB_SIZE - offset;
233:     }
234: 
235:   return esp_mipi_dsi_flush_framebuffer((FAR uint8_t *)g_tab5_fb + offset,
236:                                         len);
237: }
238: #endif /* CONFIG_FB_UPDATE */
239: 
240: /****************************************************************************
241:  * Name: tab5_fb_fill
242:  *
243:  * Description:
244:  *   Fill the framebuffer with a given color.
245:  *
246:  * Input Parameters:
247:  *   color - The color to fill the framebuffer with.
248:  *
249:  * Returned Value:
250:  *   None.
251:  *
252:  ****************************************************************************/
253: 
254: static void tab5_fb_fill(uint16_t color)
255: {
256:   size_t i;
257:   size_t npix = (size_t)TAB5_FB_WIDTH * TAB5_FB_HEIGHT;
258:   int ret;
259: 
260:   for (i = 0; i < npix; i++)
261:     {
262:       g_tab5_fb[i] = color;
263:     }
264: 
265:   ret = esp_mipi_dsi_flush_framebuffer(g_tab5_fb, TAB5_FB_SIZE);
266:   if (ret < 0)
267:     {
268:       syslog(LOG_ERR, "ERROR: FB cache C2M sync failed: %d\n", ret);
269:     }
270: }
271: 
272: /****************************************************************************
273:  * Public Functions
274:  ****************************************************************************/
275: 
276: /****************************************************************************
277:  * Name: up_fbinitialize
278:  *
279:  * Description:
280:  *   Initialize the framebuffer.
281:  *
282:  * Input Parameters:
283:  *   display - The display number.
284:  *
285:  * Returned Value:
286:  *   Zero on success, -ENODEV on failure.
287:  *
288:  ****************************************************************************/
289: 
290: int up_fbinitialize(int display)
291: {
292:   FAR struct mipi_dsi_host *host;
293:   FAR struct mipi_dsi_device *device;
294:   struct esp_mipi_dsi_dpi_config_s dpi;
295:   int ret;
296: 
297:   if (display != 0)
298:     {
299:       return -ENODEV;
300:     }
301: 
302:   if (g_tab5_fb_ready)
303:     {
304:       return OK;
305:     }
306: 
307:   g_tab5_fb = kumm_memalign(64, TAB5_FB_SIZE);
308:   if (g_tab5_fb == NULL)
309:     {
310:       syslog(LOG_ERR,
311:              "ERROR: FB alloc failed (%u bytes; enable PSRAM)\n",
312:              (unsigned int)TAB5_FB_SIZE);
313:       return -ENOMEM;
314:     }
315: 
316:   memset(g_tab5_fb, 0, TAB5_FB_SIZE);
317:   g_tab5_plane.fbmem = g_tab5_fb;
318: 
319:   host = esp_mipi_dsi_host_get();
320:   if (host == NULL)
321:     {
322:       syslog(LOG_ERR,
323:              "ERROR: MIPI-DSI host not ready "
324:              "(enable ESP32P4_TAB5_MIPI_DSI)\n");
325:       ret = -EAGAIN;
326:       goto errout_fb;
327:     }
328: 
329:   /* IDF order: DPI config before panel DCS; display_on after video_start. */
330: 
331:   syslog(LOG_INFO, "Configuring DPI...\n");
332:   tab5_mipi_dsi_dpi_config(&dpi);
333:   ret = esp_mipi_dsi_configure_dpi(&dpi);
334:   if (ret < 0)
335:     {
336:       syslog(LOG_ERR, "ERROR: configure_dpi failed: %d\n", ret);
337:       goto errout_fb;
338:     }
339: 
340:   syslog(LOG_INFO, "%s panel init...\n",
341:          TAB5_LCD_PANEL_NAME);
342:   device = tab5_panel_initialize(host);
343:   if (device == NULL)
344:     {
345:       ret = -EIO;
346:       goto errout_fb;
347:     }
348: 
349:   ret = esp_mipi_dsi_bind_framebuffer(g_tab5_fb, TAB5_FB_SIZE,
350:                                       TAB5_FB_WIDTH, TAB5_FB_HEIGHT,
351:                                       TAB5_FB_BPP);
352:   if (ret < 0)
353:     {
354:       syslog(LOG_ERR, "ERROR: bind_framebuffer failed: %d\n", ret);
355:       goto errout_fb;
356:     }
357: 
358:   tab5_fb_fill(TAB5_FB_TEST_COLOR);
359: 
360:   ret = mipi_dsi_dcs_exit_sleep_mode(device);
361:   if (ret < 0)
362:     {
363:       syslog(LOG_ERR, "ERROR: pre-video sleep_out failed: %d\n",
364:              ret);
365:       goto errout_fb;
366:     }
367: 
368:   up_mdelay(120);
369: 
370:   syslog(LOG_INFO, "Starting video...\n");
371:   ret = esp_mipi_dsi_video_start();
372:   if (ret < 0)
373:     {
374:       syslog(LOG_ERR, "ERROR: video_start failed: %d\n", ret);
375:       goto errout_fb;
376:     }
377: 
378:   ret = mipi_dsi_dcs_set_display_on(device);
379:   if (ret < 0)
380:     {
381:       syslog(LOG_ERR, "ERROR: post-video display_on failed: %d\n",
382:              ret);
383:       goto errout_fb;
384:     }
385: 
386:   tab5_fb_fill(TAB5_FB_TEST_COLOR);
387: 
388:   ret = tab5_lcd_backlight(true);
389:   if (ret < 0)
390:     {
391:       syslog(LOG_ERR, "ERROR: backlight failed: %d\n", ret);
392:     }
393: 
394:   g_tab5_fb_ready = true;
395:   syslog(LOG_INFO,
396:          "/dev/fb0 ready %ux%u RGB565 @ %p\n",
397:          TAB5_FB_WIDTH, TAB5_FB_HEIGHT, g_tab5_fb);
398: 
399: #ifdef CONFIG_ESP32P4_TAB5_LCD_APO_TEST
400:   /* White flash proves DCS/BL; then restore normal mode + red FB. */
401: 
402:   mipi_dsi_dcs_write(device, TAB5_DCS_ALL_PIXELS_ON, NULL, 0);
403:   up_mdelay(TAB5_APO_TEST_MS);
404:   mipi_dsi_dcs_write(device, TAB5_DCS_ALL_PIXELS_OFF, NULL, 0);
405:   mipi_dsi_dcs_write(device, MIPI_DCS_ENTER_NORMAL_MODE, NULL, 0);
406:   mipi_dsi_dcs_set_display_on(device);
407:   tab5_fb_fill(TAB5_FB_TEST_COLOR);
408: #endif
409: 
410:   return OK;
411: 
412: errout_fb:
413:   kumm_free(g_tab5_fb);
414:   g_tab5_fb = NULL;
415:   g_tab5_plane.fbmem = NULL;
416:   return ret;
417: }
418: 
419: /****************************************************************************
420:  * Name: up_fbgetvplane
421:  *
422:  * Description:
423:  *   Return the framebuffer vtable.
424:  *
425:  * Input Parameters:
426:  *   display - The display number.
427:  *   vplane - The vplane number.
428:  *
429:  * Returned Value:
430:  *   Pointer to the vtable on success, NULL on failure.
431:  *
432:  ****************************************************************************/
433: 
434: FAR struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
435: {
436:   if (display != 0 || vplane != 0 || !g_tab5_fb_ready)
437:     {
438:       return NULL;
439:     }
440: 
441:   return &g_tab5_vtable;
442: }
443: 
444: /****************************************************************************
445:  * Name: up_fbuninitialize
446:  *
447:  * Description:
448:  *   Uninitialize the framebuffer.
449:  *
450:  * Input Parameters:
451:  *   display - The display number.
452:  *
453:  * Returned Value:
454:  *   None.
455:  *
456:  ****************************************************************************/
457: 
458: void up_fbuninitialize(int display)
459: {
460:   UNUSED(display);
461: }
462: 
463: /****************************************************************************
464:  * Name: tab5_fb_reload_test_pattern
465:  *
466:  * Description:
467:  *   Call after fb_register(): the generic FB driver memset()s the
468:  *   framebuffer and would otherwise leave a black DMA buffer.
469:  *   This sets the framebuffer to the test color (red).
470:  *
471:  * Returned Value:
472:  *   Zero on success, -EAGAIN on failure.
473:  *
474:  ****************************************************************************/
475: 
476: int tab5_fb_reload_test_pattern(void)
477: {
478:   if (!g_tab5_fb_ready || g_tab5_fb == NULL)
479:     {
480:       return -EAGAIN;
481:     }
482: 
483:   tab5_fb_fill(TAB5_FB_TEST_COLOR);
484:   return OK;
485: }

