343:           syslog(LOG_ERR,
344:                  "ERROR: DCS 0x%02x failed: %zd (cmd %u/%u)\n",
345:                  cmd->cmd, n, i + 1, ST7123_INIT_COUNT);
346:           return (int)n;
347:         }
348: 
349:       if (cmd->delay_ms > 0)
350:         {
351:           up_mdelay(cmd->delay_ms);
352:         }
353:     }
354: 
355:   return OK;
356: }
