399:       syslog(LOG_ERR, "ERROR: mipi_dsi_device_register failed\n");
400:       return NULL;
401:     }
402: 
403:   device->lanes = TAB5_MIPI_DSI_LANES;
404:   device->format = MIPI_DSI_FMT_RGB565;
405:   device->mode_flags = MIPI_DSI_MODE_VIDEO | MIPI_DSI_MODE_VIDEO_BURST |
406:                        MIPI_DSI_MODE_LPM;
407:   device->hs_rate = TAB5_MIPI_DSI_LANE_BITRATE_MBPS * 1000000UL;
